<?php

date_default_timezone_set('Asia/Bangkok');
require_once __DIR__ . '/config/database.php';
$message=''; $error='';

if ($_SERVER['REQUEST_METHOD']==='POST') {
    $action=$_POST['action']??'';
    try {
        if ($action==='add') {
            $name=trim($_POST['name']??'');
            if($name==='') throw new Exception('กรุณากรอกชื่อพนักงาน');
            $s=$pdo->prepare('SELECT id FROM employees WHERE name=? LIMIT 1'); $s->execute([$name]);
            if($s->fetch()) throw new Exception('มีพนักงานชื่อนี้อยู่ในระบบแล้ว');
            $s=$pdo->prepare('INSERT INTO employees(name,is_active) VALUES(?,1)'); $s->execute([$name]);
            $message='เพิ่มพนักงานเรียบร้อยแล้ว';
        } elseif ($action==='edit') {
            $id=(int)($_POST['id']??0); $name=trim($_POST['name']??'');
            if($id<=0) throw new Exception('ไม่พบรหัสพนักงาน');
            if($name==='') throw new Exception('กรุณากรอกชื่อพนักงาน');
            $s=$pdo->prepare('SELECT id FROM employees WHERE name=? AND id<>? LIMIT 1'); $s->execute([$name,$id]);
            if($s->fetch()) throw new Exception('มีพนักงานชื่อนี้อยู่ในระบบแล้ว');
            $s=$pdo->prepare('UPDATE employees SET name=? WHERE id=?'); $s->execute([$name,$id]);
            $message='แก้ไขข้อมูลพนักงานเรียบร้อยแล้ว';
        } elseif ($action==='toggle') {
            $id=(int)($_POST['id']??0); if($id<=0) throw new Exception('ไม่พบรหัสพนักงาน');
            $s=$pdo->prepare('SELECT is_active FROM employees WHERE id=?'); $s->execute([$id]); $e=$s->fetch();
            if(!$e) throw new Exception('ไม่พบข้อมูลพนักงาน');
            $new=$e['is_active']?0:1; $s=$pdo->prepare('UPDATE employees SET is_active=? WHERE id=?'); $s->execute([$new,$id]);
            $message=$new?'เปิดใช้งานพนักงานเรียบร้อยแล้ว':'ปิดใช้งานพนักงานเรียบร้อยแล้ว';
        }
    } catch(Exception $e){$error=$e->getMessage();}
}

$search=trim($_GET['search']??'');
$sql="SELECT e.id,e.name,e.is_active,e.created_at,
 COALESCE(COUNT(r.id),0) work_count,
 COALESCE(SUM(r.daily_sales),0) total_sales,
 COALESCE(SUM(r.member_notifications),0) total_notifications,
 (SELECT r2.position_snapshot FROM employee_work_records r2 WHERE r2.employee_id=e.id ORDER BY r2.work_date DESC,r2.id DESC LIMIT 1) current_position,
 (SELECT r3.building_snapshot FROM employee_work_records r3 WHERE r3.employee_id=e.id ORDER BY r3.work_date DESC,r3.id DESC LIMIT 1) latest_building
 FROM employees e LEFT JOIN employee_work_records r ON r.employee_id=e.id WHERE 1=1";
$params=[]; if($search!==''){ $sql.=' AND e.name LIKE ?'; $params[]='%'.$search.'%'; }
$sql.=' GROUP BY e.id,e.name,e.is_active,e.created_at ORDER BY e.is_active DESC,e.name ASC';
$s=$pdo->prepare($sql); $s->execute($params); $employees=$s->fetchAll();
$totalEmployees=count($employees); $activeEmployees=0; $inactiveEmployees=0; foreach($employees as $e){if((int)$e['is_active'])$activeEmployees++;else$inactiveEmployees++;}

// ภาพรวมการส่งข้อมูลล่าสุด: ใช้ตรวจสอบว่าใครกรอกข้อมูลแล้ว โดยไม่ปนกับประวัติรายบุคคล
$latestRecordsStmt=$pdo->query("SELECT r.id,r.work_date,r.position_snapshot,r.building_snapshot,r.member_notifications,r.daily_sales,r.notes,e.id employee_id,e.name employee_name FROM employee_work_records r INNER JOIN employees e ON e.id=r.employee_id ORDER BY r.work_date DESC,r.id DESC LIMIT 30");
$latestRecords=$latestRecordsStmt->fetchAll();

$selectedId=(int)($_GET['employee_id']??0); $selected=null; $history=[];
if($selectedId>0){
    $s=$pdo->prepare("SELECT e.*, (SELECT r.position_snapshot FROM employee_work_records r WHERE r.employee_id=e.id ORDER BY r.work_date DESC,r.id DESC LIMIT 1) current_position FROM employees e WHERE e.id=? LIMIT 1");
    $s->execute([$selectedId]); $selected=$s->fetch();
    if($selected){
        $s=$pdo->prepare("SELECT work_date,position_snapshot,building_snapshot,member_notifications,daily_sales,notes FROM employee_work_records WHERE employee_id=? ORDER BY work_date DESC,id DESC LIMIT 100");
        $s->execute([$selectedId]); $history=$s->fetchAll();
    }
}
function money($v){return number_format((float)$v,2);}
?>
