<div id="editModal" class="modal"><div class="modal-box"><div class="modal-title">✏️ แก้ไขข้อมูลพนักงาน</div><form method="post"><input type="hidden" name="action" value="edit"><input type="hidden" name="id" id="edit_id"><div class="form-group"><label class="form-label">ชื่อพนักงาน</label><input type="text" name="name" id="edit_name" class="form-control" required></div><div class="modal-actions"><button type="button" class="btn btn-light" onclick="closeEditModal()">ยกเลิก</button><button type="submit" class="btn btn-primary">💾 บันทึกการแก้ไข</button></div></form></div></div>
<script>function openEditModal(id,name){const modal=document.getElementById('editModal');const idInput=document.getElementById('edit_id');const nameInput=document.getElementById('edit_name');if(!modal||!idInput||!nameInput)return;idInput.value=id;nameInput.value=name||'';modal.style.display='flex';document.body.style.overflow='hidden';setTimeout(function(){nameInput.focus();nameInput.select()},50)}function closeEditModal(){const modal=document.getElementById('editModal');if(modal)modal.style.display='none';document.body.style.overflow=''}function confirmToggle(active){return confirm(active?'ต้องการปิดใช้งานพนักงานคนนี้หรือไม่?':'ต้องการเปิดใช้งานพนักงานคนนี้หรือไม่?')}window.addEventListener('click',function(e){const m=document.getElementById('editModal');if(e.target===m)closeEditModal()});</script></body></html>
